import csv
import io
import re


def parse_csv(raw_csv: str):
    reader = csv.reader(
        io.StringIO(raw_csv.lstrip("\ufeff"), newline=""),
        delimiter=";",
        quotechar='"',
        doublequote=True,
        strict=False,
    )
    records = list(reader)

    # Locate the schema row, allowing harmless preamble lines before it.
    header_index = next(
        (
            i
            for i, row in enumerate(records)
            if row and row[0].strip().lstrip("\ufeff").upper() == "STRUCTURE"
        ),
        None,
    )

    if header_index is None:
        nonempty = [row for row in records if row]
        if not nonempty:
            return {"columns": [], "rows": []}
        header_index = 0

    columns = [value.strip() for value in records[header_index]]
    rows = records[header_index + 1 :]

    # Keep every parsed record, making ragged records rectangular without
    # discarding any fields from wider records.
    width = max([len(columns), 32] + [len(row) for row in rows])
    if len(columns) < width:
        columns.extend(f"__extra_{i}" for i in range(1, width - len(columns) + 1))

    normalized = []
    for row in rows:
        if len(row) < width:
            row = row + [""] * (width - len(row))
        normalized.append(row)

    return {"columns": columns, "rows": normalized}
